#import "PDFLibraryViewController.h"
#import "PDFReaderViewController.h"
#import "RecentStore.h"
@implementation PDFLibraryViewController
- (void)viewDidLoad{[super viewDidLoad];self.title=@"PDF Dosyaları";self.navigationItem.rightBarButtonItem=[[[UIBarButtonItem alloc]initWithBarButtonSystemItem:UIBarButtonSystemItemAdd target:self action:@selector(importURL)]autorelease];_emptyLabel=[[UILabel alloc]initWithFrame:CGRectZero];_emptyLabel.textAlignment=NSTextAlignmentCenter;_emptyLabel.numberOfLines=0;_emptyLabel.backgroundColor=[UIColor clearColor];_emptyLabel.text=@"Henüz PDF yok.

+ ile HTTP/FTP adresinden indirin
veya iTunes File Sharing kullanın.";[self.tableView addSubview:_emptyLabel];[self reloadPDFList];}
- (void)viewWillAppear:(BOOL)a{[super viewWillAppear:a];[self reloadPDFList];}
- (void)viewDidLayoutSubviews{[super viewDidLayoutSubviews];_emptyLabel.frame=CGRectMake(30,120,self.tableView.bounds.size.width-60,180);}
- (NSString*)documentsDirectory{NSArray*p=NSSearchPathForDirectoriesInDomains(NSDocumentDirectory,NSUserDomainMask,YES);return [p count]?[p objectAtIndex:0]:[NSHomeDirectory()stringByAppendingPathComponent:@"Documents"];}
- (void)reloadPDFList{NSString*d=[self documentsDirectory];[[NSFileManager defaultManager]createDirectoryAtPath:d withIntermediateDirectories:YES attributes:nil error:nil];NSArray*c=[[NSFileManager defaultManager]contentsOfDirectoryAtPath:d error:nil];NSMutableArray*a=[NSMutableArray array];for(NSString*n in c)if([[[n pathExtension]lowercaseString]isEqualToString:@"pdf"])[a addObject:n];[a sortUsingSelector:@selector(localizedCaseInsensitiveCompare:)];[_pdfFiles release];_pdfFiles=[a copy];_emptyLabel.hidden=[a count]>0;[self.tableView reloadData];}
- (NSInteger)tableView:(UITableView*)t numberOfRowsInSection:(NSInteger)s{return [_pdfFiles count];}
- (UITableViewCell*)tableView:(UITableView*)t cellForRowAtIndexPath:(NSIndexPath*)i{static NSString*cid=@"pdf";UITableViewCell*c=[t dequeueReusableCellWithIdentifier:cid];if(!c)c=[[[UITableViewCell alloc]initWithStyle:UITableViewCellStyleSubtitle reuseIdentifier:cid]autorelease];NSString*n=[_pdfFiles objectAtIndex:i.row];NSString*p=[[self documentsDirectory]stringByAppendingPathComponent:n];NSDictionary*a=[[NSFileManager defaultManager]attributesOfItemAtPath:p error:nil];c.textLabel.text=[n stringByDeletingPathExtension];c.detailTextLabel.text=[NSString stringWithFormat:@"%@ %.1f MB",[RecentStore isFavoritePath:p]?@"★":@"",[[a objectForKey:NSFileSize]doubleValue]/1048576.0];c.accessoryType=UITableViewCellAccessoryDetailDisclosureButton;return c;}
- (void)tableView:(UITableView*)t didSelectRowAtIndexPath:(NSIndexPath*)i{NSString*p=[[self documentsDirectory]stringByAppendingPathComponent:[_pdfFiles objectAtIndex:i.row]];[RecentStore touchPath:p];[self.navigationController pushViewController:[[[PDFReaderViewController alloc]initWithPDFPath:p]autorelease] animated:YES];}
- (void)tableView:(UITableView*)t accessoryButtonTappedForRowWithIndexPath:(NSIndexPath*)i{[_actionIndexPath release];_actionIndexPath=[i retain];UIActionSheet*s=[[[UIActionSheet alloc]initWithTitle:@"Dosya" delegate:self cancelButtonTitle:@"İptal" destructiveButtonTitle:@"Sil" otherButtonTitles:@"Favori Aç/Kapat",@"Yeniden Adlandır",nil]autorelease];[s showInView:self.view];}
- (void)actionSheet:(UIActionSheet*)s clickedButtonAtIndex:(NSInteger)b{if(!_actionIndexPath)return;NSString*n=[_pdfFiles objectAtIndex:_actionIndexPath.row];NSString*p=[[self documentsDirectory]stringByAppendingPathComponent:n];if(b==0){[[NSFileManager defaultManager]removeItemAtPath:p error:nil];[self reloadPDFList];}else if(b==1){[RecentStore toggleFavoritePath:p];[self reloadPDFList];}else if(b==2){UIAlertView*a=[[[UIAlertView alloc]initWithTitle:@"Yeni Ad" message:nil delegate:self cancelButtonTitle:@"İptal" otherButtonTitles:@"Kaydet",nil]autorelease];a.alertViewStyle=UIAlertViewStylePlainTextInput;[a textFieldAtIndex:0].text=[n stringByDeletingPathExtension];a.tag=99;[a show];}}
- (void)alertView:(UIAlertView*)a clickedButtonAtIndex:(NSInteger)b{if(a.tag==99&&b==1&&_actionIndexPath){NSString*old=[_pdfFiles objectAtIndex:_actionIndexPath.row];NSString*src=[[self documentsDirectory]stringByAppendingPathComponent:old];NSString*nn=[[[a textFieldAtIndex:0].text stringByAppendingPathExtension:@"pdf"]lastPathComponent];NSString*dst=[[self documentsDirectory]stringByAppendingPathComponent:nn];[[NSFileManager defaultManager]moveItemAtPath:src toPath:dst error:nil];[self reloadPDFList];}}
- (void)importURL{URLImportViewController*u=[[[URLImportViewController alloc]init]autorelease];u.delegate=self;[self.navigationController pushViewController:u animated:YES];}
- (void)urlImportFinishedAtPath:(NSString*)p{[self reloadPDFList];[self.navigationController popViewControllerAnimated:YES];}
- (void)importExternalPDFURL:(NSURL*)u{if(![u isFileURL])return;NSString*dst=[[self documentsDirectory]stringByAppendingPathComponent:[[u path]lastPathComponent]];if(![[u path]isEqualToString:dst])[[NSFileManager defaultManager]copyItemAtPath:[u path] toPath:dst error:nil];[self reloadPDFList];}
- (void)dealloc{[_pdfFiles release];[_emptyLabel release];[_actionIndexPath release];[super dealloc];}
@end
